require_once 'includes/config.php';require_once 'includes/functions.php';$page_title='Create your account';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$password=$_POST['password']??'';$confirm=$_POST['confirm_password']??'';
if($name==='')$errors[]='Please enter your name.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Please enter a valid email.';if(strlen($password)<8)$errors[]='Password must contain at least 8 characters.';if($password!==$confirm)$errors[]='Passwords do not match.';
if(!$errors){$s=$pdo->prepare("SELECT tourist_id FROM tourists WHERE email=?");$s->execute([$email]);if($s->fetch())$errors[]='An account with this email already exists.';else{$s=$pdo->prepare("INSERT INTO tourists(first_name,last_name,email,password_hash,mobile_number) VALUES(?,?,?,?,?)");$parts=preg_split('/\s+/', $name, 2);$s->execute([$parts[0],$parts[1]??'', $email,password_hash($password,PASSWORD_DEFAULT),$phone]);unset($_SESSION['admin_id'], $_SESSION['admin_name']);$_SESSION['tourist_id']=(int)$pdo->lastInsertId();$_SESSION['tourist_name']=$name;flash('Welcome to TravelHub. Your account is ready.');header('Location: dashboard.php');exit;}}
